#include <IQM/hdrvdp3/srgb_quality96_runtime_double.h>
#include <vulkan_instance.h>
#include <fstream>
#include <iostream>
#include <bit>
#include <limits>
using namespace IQM::HDRVDP3;namespace fs=std::filesystem;
std::vector<double> readRow(const fs::path&p,unsigned w){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(w*w*8))throw std::runtime_error("Reference shape");std::vector<double> v(w*w),row(w*w);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),v.size()*8);for(unsigned y=0;y<w;++y)for(unsigned x=0;x<w;++x)row[y*w+x]=v[x*w+y];return row;}
int main(int argc,char**argv){try{if(argc!=4)throw std::invalid_argument("Usage: v4-runtime cpu-root fresh-output");fs::path runtime=argv[1],cpu=argv[2],out=argv[3];if(fs::exists(out)||!fs::create_directories(out))throw std::invalid_argument("Fresh output");auto model=load_srgb_quality96_runtime_double(runtime,"oled");IQM::Bin::VulkanInstance instance(true,"NVIDIA",true);SRGBQuality96GPUDouble gpu(*instance.physicalDevice(),*instance.device(),*instance.queue(),instance.queueFamilyIndex,true,model.shaders,model.projection,model.mutual,model.neighbor);size_t words=0;auto compare=[&](auto&a,auto&b){if(a.size()!=b.size())throw std::runtime_error("Shape");for(size_t i=0;i<a.size();++i)if(std::bit_cast<uint64_t>(a[i])!=std::bit_cast<uint64_t>(b[i]))throw std::runtime_error("Neighbor bits at "+std::to_string(i));words+=a.size();};const unsigned widths[]{96,96,48,24,12};
 for(std::string native:{"native","native_ramps","native_identity_v2"})for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"}){std::vector<std::vector<double>> masks;for(unsigned b=0;b<5;++b)masks.push_back(readRow(cpu/native/(display+"_quality_band"+std::to_string(b+1)+"_self.f64"),widths[b]));for(unsigned b=0;b<5;++b){auto result=gpu.neighbor(masks,b),expected=readRow(cpu/native/(display+"_quality_band"+std::to_string(b+1)+"_neighbor.f64"),widths[b]);compare(result,expected);std::ofstream f(out/(native+"_"+display+"_band"+std::to_string(b+1)+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(result.data()),result.size()*8);}}
 const size_t nativeWords=words;for(unsigned seed=0;seed<3;++seed){std::vector<std::vector<double>> masks;for(unsigned b=0;b<5;++b){unsigned w=widths[b];std::vector<double> v(w*w);for(size_t i=0;i<v.size();++i)v[i]=seed==0?(i%19==0?1.:0.):seed==1?double((i+b)%97)*.013:(i%7==0?1e6:1e-12);masks.push_back(std::move(v));}for(unsigned b=0;b<5;++b){auto result=gpu.neighbor(masks,b),expected=quality_neighbor_mask_double(masks,b);compare(result,expected);}}
 unsigned rejected=0;auto reject=[&](auto action){try{action();}catch(const std::exception&){++rejected;return;}throw std::runtime_error("Invalid neighbor input accepted");};std::vector<std::vector<double>> masks;for(unsigned w:widths)masks.emplace_back(w*w,1.);reject([&]{gpu.neighbor({},0);});reject([&]{gpu.neighbor(masks,5);});masks[0].pop_back();reject([&]{gpu.neighbor(masks,0);});masks[0].push_back(1.);for(double value:{-1.,std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity()}){masks[0][0]=value;reject([&]{gpu.neighbor(masks,0);});}std::ofstream(out/"PASS.txt")<<nativeWords<<" native Double neighbor words exact;"<<words-nativeWords<<" control words exact;"<<rejected<<" rejection checks\n";std::cout<<words<<" neighbor words exact\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
